create or replace function private.require_lesson_video() returns trigger language plpgsql security invoker set search_path='' as $$ begin if new.published and (nullif(trim(new.quick_answer),'') is null or nullif(trim(new.body),'') is null or new.review_status<>'reviewed') then raise exception 'Review the written guide and add a quick answer before publishing';end if;return new;end $$;
